{
  "name": "@xzy-ai/opencode-commandcode-provider",
  "version": "0.1.3",
  "description": "Command Code provider plugin for opencode.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "commandcode",
    "ai-sdk",
    "provider"
  ],
  "license": "MIT",
  "author": "Budisantoso",
  "sideEffects": false,
  "dependencies": {
    "@ai-sdk/provider": "latest",
    "@opencode-ai/plugin": "1.18.4"
  },
  "devDependencies": {
    "@types/node": "latest",
    "typescript": "^5"
  },
  "peerDependencies": {
    "typescript": "^5"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit"
  }
}
